@@ -2327,20 +2328,22 @@ void UpdateNeedsHoleCheck(Variable* var, VariableProxy* proxy, Scope* scope) {
   // scopes, to ensure tests are done in cases like the following:
   //   switch (1) { case 0: let x = 2; case 1: f(x); }
